window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-787880896a81447b"]={"versions": [{"id": "FIG-787880896a81447b", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR VFB Software-Architekturdiagramm (UML 2.0 Composite Structure Diagram).</li>\n<li><strong>Kontext & Zweck:</strong> Darstellung des Entwurfsmusters <em>Actuator without Feedback Loop (Setpoint Alternative)</em> aus dem <em>AUTOSAR Application Interfaces Design Patterns Catalogue</em> (TR AIDesignPatternsCatalogue, Kap. 3).</li>\n<li><strong>Funktionale Einordnung:</strong> Kapselung eines gesteuerten Aktuators (Open-Loop Actuator) innerhalb einer Komposition (<code>CompositionSwComponentType</code>). Da kein physikalischer Sensor zur Rückmeldung des Istwerts existiert, spiegelt/schätzt ein virtueller Sensor (<code>DevSnsrVirt</code>) den Anlagenzustand ausschließlich anhand des bereitgestellten Sollwerts (<code>Sp</code>) und stellt diesen als konsolidiertes Feedback (<code>Consold</code>) für übergeordnete Regler/Applikationen bereit.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Hüllkomponente (<code>Device Abstraction</code>):</strong></li>\n<li>Typ: <code>CompositionSwComponentType</code> (gekennzeichnet durch das Drei-Boxen-Symbol oben rechts).</li>\n<li>Äußere Ports:</li>\n<li><code>Reqd</code> (RPortPrototype, Sender-Receiver): Eingang für übergeordnete Funktionsanforderungen (z. B. Wunschposition, Betriebsmodus).</li>\n<li><code>Consold</code> (PPortPrototype, Sender-Receiver): Ausgang für den konsolidierten/virtuellen Anlagenzustand.</li>\n<li>Unterer Port: Hardware-Schnittstelle (elektrische Pins bzw. MCAL/IoHwAb-Verbindung).</li>\n<li><strong>Interne Software-Komponenten (<code>SwComponentPrototype : SwComponentType</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevCoorrVirt : DevCoorrVirt</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>ApplicationSwComponentType</code> (Symbol: einfaches Rechteck).</li>\n<li>Funktion: Koordinator für Aktor-Anforderungen (Arbitrierung, Plausibilisierung, Sollwert-Rampen).</li>\n<li>Ports: RPort für <code>Reqd</code>, PPort für Sollwert <code>Sp</code> (Setpoint).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevDrvrActr : DevDrvrActr</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>ApplicationSwComponentType</code> (Symbol: einfaches Rechteck).</li>\n<li>Funktion: Logischer Aktortreiber; setzt den Sollwert <code>Sp</code> in aktorspezifische Stellgrößen um.</li>\n<li>Ports: RPort für <code>Sp</code>, PPort für Aktor-Ansteuerung <code>Outp</code> (Output).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DrvrActrElec : DrvrActrElec</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>SensorActuatorSwComponentType</code> (Symbol: Aktor-Diagonalsymbol/Pfeil unten rechts).</li>\n<li>Funktion: Elektrischer Endstufen-Treiber; wandelt logische Stellgrößen in elektrische Signale (z. B. PWM, H-Brücke, SPI/DIO-Befehle) um.</li>\n<li>Ports: RPort für <code>Outp</code>, Hardware-Port an der ECU-Grenze.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevSnsrVirt : DevSnsrVirt</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>ApplicationSwComponentType</code> (Symbol: einfaches Rechteck).</li>\n<li>Funktion: Virtueller Sensor; generiert mangels physikalischer Messung das Status-Feedback allein auf Basis des Sollwerts <code>Sp</code>.</li>\n<li>Ports: RPort für <code>Sp</code>, PPort für <code>Consold</code>.</li>\n<li><strong>Konnektoren:</strong></li>\n<li><strong>Delegation-Connectors:</strong></li>\n<li>Outer <code>Reqd</code> $\\rightarrow$ <code>DevCoorrVirt.Reqd</code>.</li>\n<li><code>DevSnsrVirt.Consold</code> $\\rightarrow$ Outer <code>Consold</code>.</li>\n<li><code>DrvrActrElec</code> HW-Port $\\rightarrow$ Outer HW-Interface.</li>\n<li><strong>Assembly-Connectors:</strong></li>\n<li>1:N-Verbindung von <code>DevCoorrVirt.Sp</code> parallel an <code>DevDrvrActr.Sp</code> und <code>DevSnsrVirt.Sp</code>.</li>\n<li>1:1-Verbindung von <code>DevDrvrActr.Outp</code> an <code>DrvrActrElec.Outp</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Anforderung (Request Phase):</strong> Eine Applikations-SW-C sendet Sollwertanforderungen über das Interface <code>Reqd</code> an die Composition.</li>\n<li><strong>Arbitrierung & Sollwertgenerierung:</strong> <code>DevCoorrVirt</code> verarbeitet die Anforderung (z. B. Begrenzung, Rampenformung) und publiziert den Sollwert <code>Sp</code>.</li>\n<li><strong>Divergierende Sollwert-Verteilung (Setpoint Alternative):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad A (Aktorik/Stellpfad):</strong></li>\n<li><code>DevDrvrActr</code> empfängt <code>Sp</code>, berechnet das Stellsignal <code>Outp</code> (z. B. Tastverhältnis, Bestromungszeit).</li>\n<li><code>DrvrActrElec</code> übernimmt <code>Outp</code> und steuert die Endstufe/Hardware über MCAL/IoHwAb an.</li>\n<li><strong>Pfad B (Virtuelles Feedback):</strong></li>\n<li><code>DevSnsrVirt</code> empfängt parallel denselben Sollwert <code>Sp</code>.</li>\n<li>Mangels Sensorrückmeldung berechnet <code>DevSnsrVirt</code> ein modellbasiertes Feedback (z. B. Verzögerungsglied $PT_1$, Totzeitmodell oder direkte Sollwert-Quittierung).</li>\n<li>Bereitstellung des Resultats über <code>Consold</code> an die übergeordnete Funktionsschicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlende Rückkopplungsschleife:</strong> Es existiert kein Rückführpfad von der physikalischen Aktorik (<code>DrvrActrElec</code>) zu <code>DevSnsrVirt</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Musterabgrenzung („Setpoint Alternative“ vs. „Output Alternative“):</strong></li>\n<li>Hier greift <code>DevSnsrVirt</code> den Sollwert <code>Sp</code> am Eingang des Aktortreibers ab.</li>\n<li><em>Unterschied zur Output-Alternative:</em> Verzögerungen, Begrenzungen oder Fehlerabschaltungen, die erst in <code>DevDrvrActr</code> oder <code>DrvrActrElec</code> stattfinden, werden von <code>DevSnsrVirt</code> nicht erfasst.</li>\n<li><strong>RTE-Konfiguration & Datenfluss:</strong></li>\n<li>Für <code>Sp</code> muss im RTE-Generator eine 1:N-Kommunikationsbeziehung konfiguriert werden (<code>ComSpec</code> mit passender Queue- oder Last-Value-Semantik, typischerweise unqueued Sender-Receiver).</li>\n<li>Datenkonsistenz zwischen <code>DevDrvrActr</code> und <code>DevSnsrVirt</code> erfordert ggf. synchrone Task-Zuordnung oder RTE-Pufferung (<code>Rte_IRead</code> / <code>Rte_Read</code>).</li>\n<li><strong>BSW- und Treiberanbindung:</strong></li>\n<li><code>DrvrActrElec</code> als <code>SensorActuatorSwComponentType</code> ist an die spezifische ECU gebunden (keine freie Allokation über Netzwerk), da er direkte BSW-/Hardware-Dienste nutzt.</li>\n<li>Diagnosemeldungen (Kurzschluss, Leitungsbruch) müssen durch <code>DrvrActrElec</code> separat über <code>DiagnosticMonitor</code> (Dem) bzw. <code>Det</code> gemeldet werden, da <code>DevSnsrVirt</code> solche Fehler nicht aus Messwerten ableiten kann.</li>\n</ul>"}, {"id": "FIG-c94754c89f4c3dc1", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR VFB Software-Architekturdiagramm (UML 2.0 Composite Structure Diagram).</li>\n<li><strong>Kontext & Zweck:</strong> Darstellung des Entwurfsmusters <em>Actuator without Feedback Loop (Setpoint Alternative)</em> aus dem <em>AUTOSAR Application Interfaces Design Patterns Catalogue</em> (TR AIDesignPatternsCatalogue, Kap. 3).</li>\n<li><strong>Funktionale Einordnung:</strong> Kapselung eines gesteuerten Aktuators (Open-Loop Actuator) innerhalb einer Komposition (<code>CompositionSwComponentType</code>). Da kein physikalischer Sensor zur Rückmeldung des Istwerts existiert, spiegelt/schätzt ein virtueller Sensor (<code>DevSnsrVirt</code>) den Anlagenzustand ausschließlich anhand des bereitgestellten Sollwerts (<code>Sp</code>) und stellt diesen als konsolidiertes Feedback (<code>Consold</code>) für übergeordnete Regler/Applikationen bereit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Hüllkomponente (<code>Device Abstraction</code>):</strong></li>\n<li>Typ: <code>CompositionSwComponentType</code> (gekennzeichnet durch das Drei-Boxen-Symbol oben rechts).</li>\n<li>Äußere Ports:</li>\n<li><code>Cpby</code> (PPortPrototype, Sender-Receiver): Bereitstellung von Aktor-Fähigkeiten/Status (Capability).</li>\n<li><code>Reqd</code> (RPortPrototype, Sender-Receiver): Eingang für übergeordnete Funktionsanforderungen.</li>\n<li><code>Consold</code> (PPortPrototype, Sender-Receiver): Ausgang für den konsolidierten/virtuellen Anlagenzustand.</li>\n<li>Unterer Port: Hardware-Schnittstelle (elektrische Pins bzw. MCAL/IoHwAb-Verbindung).</li>\n<li><strong>Interne Software-Komponenten (<code>SwComponentPrototype : SwComponentType</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevCoorrVirt: DevCoorrVirt</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>CompositionSwComponentType</code> (Symbol: Drei-Boxen-Icon).</li>\n<li>Funktion: Koordinator für Aktor-Anforderungen (Arbitrierung, Plausibilisierung, Sollwert-Rampen).</li>\n<li>Ports: RPort für <code>Reqd</code>, PPort für Sollwert <code>Sp</code> (Setpoint).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevDrvrActr : DevDrvrActr</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>CompositionSwComponentType</code> (Symbol: Drei-Boxen-Icon).</li>\n<li>Funktion: Logischer Aktortreiber; setzt den Sollwert <code>Sp</code> in aktorspezifische Stellgrößen um und meldet Fähigkeiten/Status über <code>Cpby</code>.</li>\n<li>Ports: RPort für <code>Sp</code>, PPort für <code>Outp</code>, PPort für <code>Cpby</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DrvrActrElec : DrvrActrElec</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>SensorActuatorSwComponentType</code> (Symbol: Aktor-Diagonalsymbol/Pfeil unten rechts).</li>\n<li>Funktion: Elektrischer Endstufen-Treiber; wandelt logische Stellgrößen in elektrische Signale um.</li>\n<li>Ports: RPort für <code>Outp</code>, Hardware-Port an der ECU-Grenze.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevSns rVirt : DevSns rVirt</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>CompositionSwComponentType</code> (Symbol: Drei-Boxen-Icon).</li>\n<li>Funktion: Virtueller Sensor; generiert mangels physikalischer Messung das Status-Feedback allein auf Basis des Sollwerts.</li>\n<li>Ports: RPort für <code>Measd</code> (verbunden mit <code>Sp</code>), PPort für <code>Consold</code>.</li>\n<li><strong>Konnektoren:</strong></li>\n<li><strong>Delegation-Connectors:</strong></li>\n<li>Outer <code>Reqd</code> $\\rightarrow$ <code>DevCoorrVirt.Reqd</code>.</li>\n<li><code>DevDrvrActr.Cpby</code> $\\rightarrow$ Outer <code>Cpby</code>.</li>\n<li><code>DevSns rVirt.Consold</code> $\\rightarrow$ Outer <code>Consold</code>.</li>\n<li><code>DrvrActrElec</code> HW-Port $\\rightarrow$ Outer HW-Interface.</li>\n<li><strong>Assembly-Connectors:</strong></li>\n<li>1:N-Verbindung von <code>DevCoorrVirt.Sp</code> parallel an <code>DevDrvrActr.Sp</code> und <code>DevSns rVirt.Measd</code>.</li>\n<li>1:1-Verbindung von <code>DevDrvrActr.Outp</code> an <code>DrvrActrElec.Outp</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Anforderung (Request Phase):</strong> Eine Applikations-SW-C sendet Sollwertanforderungen über das Interface <code>Reqd</code> an die Composition.</li>\n<li><strong>Fähigkeitsmeldung (Capability Reporting):</strong> <code>DevDrvrActr</code> meldet über den Port <code>Cpby</code> die Aktor-Fähigkeiten und Verfügbarkeiten nach außen.</li>\n<li><strong>Arbitrierung & Sollwertgenerierung:</strong> <code>DevCoorrVirt</code> verarbeitet die Anforderung (z. B. Begrenzung, Rampenformung) und publiziert den Sollwert <code>Sp</code>.</li>\n<li><strong>Divergierende Sollwert-Verteilung (Setpoint Alternative):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad A (Aktorik/Stellpfad):</strong></li>\n<li><code>DevDrvrActr</code> empfängt <code>Sp</code> und übersetzt die physikalische Vorgabe in logische Steuerbefehle <code>Outp</code>.</li>\n<li><code>DrvrActrElec</code> setzt <code>Outp</code> in Ansteuersignale für die Hardware-Endstufe um.</li>\n<li><strong>Pfad B (Virtuelles Feedback):</strong></li>\n<li><code>DevSns rVirt</code> empfängt parallel denselben Sollwert über seinen Port <code>Measd</code>.</li>\n<li>Da kein echter Sensor vorhanden ist, wird auf Basis des Sollwerts der geschätzte Istwert berechnet und über <code>Consold</code> nach außen bereitgestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Muster-Charakteristik:</strong> Repräsentiert Aktuatoren ohne eigene Sensorrückführung (z. B. einfache Schrittmotoren, unüberwachte Relais/Ventile).</li>\n<li><strong>VFB-Semantik:</strong> Die parallele Verteilung von <code>Sp</code> an Treiber (<code>Sp</code>) und virtuellen Sensor (<code>Measd</code>) via 1:N-Assembly-Connector stellt sicher, dass Aktorik und virtueller Beobachter synchron arbeiten.</li>\n<li><strong>Hierarchische Schachtelung:</strong> Die Komponenten <code>DevCoorrVirt</code>, <code>DevDrvrActr</code> und <code>DevSns rVirt</code> sind als <code>CompositionSwComponentType</code> modelliert, was eine weitere interne Dekomposition ermöglicht.</li>\n<li><strong>Capability Reporting:</strong> Über <code>Cpby</code> können übergeordnete Instanzen über den Betriebszustand und Stellgrenzen des Aktors informiert werden.</li>\n</ul>"}, {"id": "FIG-fd762547066808d6", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR VFB Software-Architekturdiagramm (UML 2.0 Composite Structure Diagram).</li>\n<li><strong>Kontext & Zweck:</strong> Darstellung des Entwurfsmusters <em>Actuator without Feedback Loop (Setpoint Alternative)</em> aus dem <em>AUTOSAR Application Interfaces Design Patterns Catalogue</em> (TR AIDesignPatternsCatalogue, Kap. 3).</li>\n<li><strong>Funktionale Einordnung:</strong> Kapselung eines gesteuerten Aktuators (Open-Loop Actuator) innerhalb einer Komposition (<code>CompositionSwComponentType</code>). Da kein physikalischer Sensor zur Rückmeldung des Istwerts existiert, spiegelt/schätzt ein virtueller Sensor (<code>DevSnsrVirt</code>) den Anlagenzustand ausschließlich anhand des bereitgestellten Sollwerts (<code>Sp</code>) und stellt diesen als konsolidiertes Feedback (<code>Consold</code>) für übergeordnete Regler/Applikationen bereit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Hüllkomponente (<code>Device Abstraction</code>):</strong></li>\n<li>Typ: <code>CompositionSwComponentType</code> (gekennzeichnet durch das Drei-Boxen-Symbol oben rechts).</li>\n<li>Äußere Ports:</li>\n<li><code>Cpby</code> (PPortPrototype, Sender-Receiver): Bereitstellung von Aktor-Fähigkeiten/Status (Capability).</li>\n<li><code>Reqd</code> (RPortPrototype, Sender-Receiver): Eingang für übergeordnete Funktionsanforderungen.</li>\n<li><code>Consold</code> (PPortPrototype, Sender-Receiver): Ausgang für den konsolidierten/virtuellen Anlagenzustand.</li>\n<li>Unterer Port: Hardware-Schnittstelle <code>Actr : {componentPrototypeName}</code> (elektrische Pins bzw. MCAL/IoHwAb-Verbindung).</li>\n<li><strong>Interne Software-Komponenten (<code>SwComponentPrototype : SwComponentType</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevCoorrVirt : DevCoorrVirt</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>CompositionSwComponentType</code> (Symbol: Drei-Boxen-Icon).</li>\n<li>Funktion: Koordinator für Aktor-Anforderungen (Arbitrierung, Plausibilisierung, Sollwert-Rampen).</li>\n<li>Ports: RPort für <code>Reqd</code>, PPort für Sollwert <code>Sp</code> (Setpoint).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevDrvrActr : DevDrvrActr</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>CompositionSwComponentType</code> (Symbol: Drei-Boxen-Icon).</li>\n<li>Funktion: Logischer Aktortreiber; setzt den Sollwert <code>Sp</code> in aktorspezifische Stellgrößen um und meldet Fähigkeiten/Status über <code>Cpby</code>.</li>\n<li>Ports: RPort für <code>Sp</code>, PPort für <code>Outp</code>, PPort für <code>Cpby</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DrvrActrElec : DrvrActrElec</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>SensorActuatorSwComponentType</code> (Symbol: Aktor-Diagonalsymbol/Pfeil unten rechts).</li>\n<li>Funktion: Elektrischer Endstufen-Treiber; wandelt logische Stellgrößen in elektrische Signale um.</li>\n<li>Ports: RPort für <code>Outp</code>, Hardware-Port an der ECU-Grenze.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>DevSns rVirt : DevSns rVirt</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>CompositionSwComponentType</code> (Symbol: Drei-Boxen-Icon).</li>\n<li>Funktion: Virtueller Sensor; generiert mangels physikalischer Messung das Status-Feedback allein auf Basis des Sollwerts.</li>\n<li>Ports: RPort für <code>Measd</code> (verbunden mit <code>Sp</code>), PPort für <code>Consold</code>.</li>\n<li><strong>Konnektoren:</strong></li>\n<li><strong>Delegation-Connectors:</strong></li>\n<li>Outer <code>Reqd</code> $\\rightarrow$ <code>DevCoorrVirt.Reqd</code>.</li>\n<li><code>DevDrvrActr.Cpby</code> $\\rightarrow$ Outer <code>Cpby</code>.</li>\n<li><code>DevSns rVirt.Consold</code> $\\rightarrow$ Outer <code>Consold</code>.</li>\n<li><code>DrvrActrElec</code> HW-Port $\\rightarrow$ Outer HW-Interface <code>Actr : {componentPrototypeName}</code>.</li>\n<li><strong>Assembly-Connectors:</strong></li>\n<li>1:N-Verbindung von <code>DevCoorrVirt.Sp</code> parallel an <code>DevDrvrActr.Sp</code> und <code>DevSns rVirt.Measd</code>.</li>\n<li>1:1-Verbindung von <code>DevDrvrActr.Outp</code> an <code>DrvrActrElec.Outp</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Anforderung (Request Phase):</strong> Eine Applikations-SW-C sendet Sollwertanforderungen über das Interface <code>Reqd</code> an die Composition.</li>\n<li><strong>Fähigkeitsmeldung (Capability Reporting):</strong> <code>DevDrvrActr</code> meldet über den Port <code>Cpby</code> die Aktor-Fähigkeiten und Verfügbarkeiten nach außen.</li>\n<li><strong>Arbitrierung & Sollwertgenerierung:</strong> <code>DevCoorrVirt</code> verarbeitet die Anforderung (z. B. Begrenzung, Rampenformung) und publiziert den Sollwert <code>Sp</code>.</li>\n<li><strong>Divergierende Sollwert-Verteilung (Setpoint Alternative):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad A (Aktorik/Stellpfad):</strong></li>\n<li><code>DevDrvrActr</code> empfängt <code>Sp</code> und übersetzt die physikalische Vorgabe in logische Steuerbefehle <code>Outp</code>.</li>\n<li><code>DrvrActrElec</code> setzt <code>Outp</code> in Ansteuersignale für die Hardware-Endstufe um.</li>\n<li><strong>Pfad B (Virtuelles Feedback):</strong></li>\n<li><code>DevSns rVirt</code> empfängt parallel denselben Sollwert über seinen Port <code>Measd</code>.</li>\n<li>Da kein echter Sensor vorhanden ist, wird auf Basis des Sollwerts der geschätzte Istwert berechnet und über <code>Consold</code> nach außen bereitgestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Muster-Charakteristik:</strong> Repräsentiert Aktuatoren ohne eigene Sensorrückführung (z. B. einfache Schrittmotoren, unüberwachte Relais/Ventile).</li>\n<li><strong>VFB-Semantik:</strong> Die parallele Verteilung von <code>Sp</code> an Treiber (<code>Sp</code>) und virtuellen Sensor (<code>Measd</code>) via 1:N-Assembly-Connector stellt sicher, dass Aktorik und virtueller Beobachter synchron arbeiten.</li>\n<li><strong>Hierarchische Schachtelung:</strong> Die Komponenten <code>DevCoorrVirt</code>, <code>DevDrvrActr</code> und <code>DevSns rVirt</code> sind als <code>CompositionSwComponentType</code> modelliert, was eine weitere interne Dekomposition ermöglicht.</li>\n<li><strong>Capability Reporting:</strong> Über <code>Cpby</code> können übergeordnete Instanzen über den Betriebszustand und Stellgrenzen des Aktors informiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-787880896a81447b", "to": "FIG-c94754c89f4c3dc1", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuer Port und Delegation Connector <code>Cpby</code>: <code>DevDrvrActr</code> stellt über einen P-Port eine Capability-Schnittstelle bereit, die über einen P-Port am oberen Rand der <code>Device Abstraction</code> nach außen geführt wird.</li>\n<li>R-Port an <code>DevSnsrVirt</code> mit Schnittstellenbezeichner <code>Measd</code> beschriftet (zuvor unbeschriftet; weiterhin mit <code>Sp</code> verbunden).</li>\n<li>Komponentensymbole geändert: <code>DevCoorrVirt</code>, <code>DevDrvrActr</code> und <code>DevSnsrVirt</code> tragen nun das Drei-Boxen-Symbol (<code>CompositionSwComponentType</code>) statt des einfachen Rechtecks (<code>ApplicationSwComponentType</code>).</li>\n<li>Schreibweise im Prototypennamen geändert: <code>DevSns rVirt : DevSns rVirt</code> mit Leerzeichen vor dem <code>r</code>.</li>\n</ul>"}, {"from": "FIG-c94754c89f4c3dc1", "to": "FIG-fd762547066808d6", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textzeile am oberen Bildrand ergänzt: \"... the setpoint input, but there are alternatives how to calculate the consolidated value.\"</li>\n<li>Beschriftung der Hardware-Verbindung unten rechts präzisiert: <code>Actr : {componentPrototypeName}</code> statt <code>{componentPrototypeName} : {componentTypeName}</code>.</li>\n</ul>"}]};
